CREATE OR REPLACE FUNCTION public.import_cliente(p_cliente uuid, p_bundle jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE r jsonb; t uuid; BEGIN
IF NOT EXISTS(SELECT 1 FROM clientes WHERE id=p_cliente AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Cliente não encontrado'; END IF;
IF p_bundle ? 'empresa' THEN UPDATE clientes SET nome=COALESCE(p_bundle->'empresa'->>'nome',nome), cnpj=COALESCE(p_bundle->'empresa'->>'cnpj',cnpj), cidade_uf=COALESCE(p_bundle->'empresa'->>'cidade_uf',cidade_uf), vigencia=COALESCE((p_bundle->'empresa'->>'vigencia')::date,vigencia), aprovado_por=COALESCE(p_bundle->'empresa'->>'aprovado_por',aprovado_por), jornada_semanal=COALESCE((p_bundle->'empresa'->>'jornada_semanal')::numeric,jornada_semanal), dia_inicio=COALESCE(p_bundle->'empresa'->>'dia_inicio',dia_inicio), dia_fim=COALESCE(p_bundle->'empresa'->>'dia_fim',dia_fim), hora_entrada=COALESCE(p_bundle->'empresa'->>'hora_entrada',hora_entrada), hora_saida=COALESCE(p_bundle->'empresa'->>'hora_saida',hora_saida), intervalo=COALESCE(p_bundle->'empresa'->>'intervalo',intervalo), sistema_ponto=COALESCE(p_bundle->'empresa'->>'sistema_ponto',sistema_ponto), canal_denuncias=COALESCE(p_bundle->'empresa'->>'canal_denuncias',canal_denuncias), responsavel_apuracao=COALESCE(p_bundle->'empresa'->>'responsavel_apuracao',responsavel_apuracao), prazo_apuracao_dias=COALESCE((p_bundle->'empresa'->>'prazo_apuracao_dias')::int,prazo_apuracao_dias), valor_max_brindes=COALESCE((p_bundle->'empresa'->>'valor_max_brindes')::numeric,valor_max_brindes), mensagem_lideranca=COALESCE(p_bundle->'empresa'->>'mensagem_lideranca',mensagem_lideranca), incluir_notas_consultor=COALESCE((p_bundle->'empresa'->>'incluir_notas_consultor')::boolean,incluir_notas_consultor) WHERE id=p_cliente; END IF;
IF p_bundle ? 'colaboradores' THEN DELETE FROM colaboradores WHERE cliente_id=p_cliente; FOR r IN SELECT value FROM jsonb_array_elements(p_bundle->'colaboradores') LOOP INSERT INTO colaboradores(cliente_id,nome,cargo,departamento,admissao,posto) VALUES(p_cliente,r->>'nome',r->>'cargo',r->>'departamento',NULLIF(r->>'admissao','')::date,r->>'posto'); END LOOP; END IF;
IF p_bundle ? 'postos' THEN DELETE FROM postos WHERE cliente_id=p_cliente; END IF;
IF p_bundle ? 'turnos' THEN
FOR r IN SELECT value FROM jsonb_array_elements(p_bundle->'turnos') LOOP
SELECT id INTO t FROM turnos WHERE cliente_id=p_cliente AND (lower(unaccent_name(nome))=lower(unaccent_name(r->>'nome')) OR (NULLIF(r->>'sigla','') IS NOT NULL AND lower(unaccent_name(sigla))=lower(unaccent_name(r->>'sigla')))) LIMIT 1;
IF t IS NULL THEN INSERT INTO turnos(cliente_id,nome,sigla,inicio,fim,intervalo_min) VALUES(p_cliente,r->>'nome',r->>'sigla',r->>'inicio',r->>'fim',(r->>'intervalo_min')::int);
ELSE UPDATE turnos SET nome=r->>'nome',sigla=r->>'sigla',inicio=r->>'inicio',fim=r->>'fim',intervalo_min=(r->>'intervalo_min')::int WHERE id=t; END IF;
END LOOP;
IF EXISTS(SELECT 1 FROM turnos x JOIN postos p ON p.turno_id=x.id WHERE x.cliente_id=p_cliente AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_bundle->'turnos') j WHERE lower(unaccent_name(j->>'nome'))=lower(unaccent_name(x.nome)) OR (NULLIF(j->>'sigla','') IS NOT NULL AND lower(unaccent_name(j->>'sigla'))=lower(unaccent_name(x.sigla))))) THEN RAISE EXCEPTION 'Um turno removido ainda é usado por um posto. Inclua a aba Postos com os novos vínculos.'; END IF;
DELETE FROM turnos x WHERE cliente_id=p_cliente AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_bundle->'turnos') j WHERE lower(unaccent_name(j->>'nome'))=lower(unaccent_name(x.nome)) OR (NULLIF(j->>'sigla','') IS NOT NULL AND lower(unaccent_name(j->>'sigla'))=lower(unaccent_name(x.sigla))));
END IF;
IF p_bundle ? 'postos' THEN FOR r IN SELECT value FROM jsonb_array_elements(p_bundle->'postos') LOOP SELECT id INTO t FROM turnos WHERE cliente_id=p_cliente AND (lower(unaccent_name(nome))=lower(unaccent_name(r->>'turno')) OR lower(unaccent_name(sigla))=lower(unaccent_name(r->>'turno'))) LIMIT 1; IF t IS NULL THEN RAISE EXCEPTION 'Turno não encontrado: %',r->>'turno'; END IF; INSERT INTO postos(cliente_id,posto,turno_id,pessoas_por_dia,escala,operacao) VALUES(p_cliente,r->>'posto',t,(r->>'pessoas_por_dia')::int,r->>'escala',r->>'operacao'); END LOOP; END IF;
IF p_bundle ? 'cargos' THEN DELETE FROM cargos WHERE cliente_id=p_cliente; FOR r IN SELECT value FROM jsonb_array_elements(p_bundle->'cargos') LOOP INSERT INTO cargos(cliente_id,familia,cargo,nivel,trilha,salario_base,tempo_minimo_meses,requisitos) VALUES(p_cliente,r->>'familia',r->>'cargo',(r->>'nivel')::int,r->>'trilha',(r->>'salario_base')::numeric,(r->>'tempo_minimo_meses')::int,r->>'requisitos'); END LOOP; END IF;
END $$;